	return toError(fnsDDMMPreprocess(handle, opA, opB, alpha.arg(&_scalars[0]), matA, matB, beta.arg(&_scalars[1]), matC, computeType, alg, uintptr(externalBuffer)), "cusparseSDDMM_preprocess")
